TLM.f("Tempora/Quad5-1",{"officium":"Feria Secunda infra Hebdomadam Passionis","rule":["no Gloria","Suffragium=Ecclesiæ,Papa;;","Prefatio=Quad5","Super popul"],"ruleInherited":["no Gloria","Credo","Prefatio=Quad5","Suffragium=Ecclesiæ,Papa;;"],"fallback":"Tempora/Quad5-0","sections":{"Introitus":[{"k":"ref","la":"Ps 55:2"},{"k":"text","la":"Miserére mihi, Dómine, quóniam conculcávit me homo: tota die bellans tribulávit me."},{"k":"ref","la":"Ps 55:3"},{"k":"text","la":"Conculcavérunt me inimíci mei tota die: quóniam multi bellántes advérsum me."},{"k":"text","la":"Miserére mihi, Dómine, quóniam conculcávit me homo: tota die bellans tribulávit me."}],"Oratio":[{"k":"text","la":"Sanctífica, quǽsumus, Dómine, nostra jejúnia: et cunctárum nobis indulgéntiam propítius largíre culpárum."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Jonæ Prophétæ."},{"k":"ref","la":"Jonæ 3:1-10"},{"k":"text","la":"In diébus illis: Factum est verbum Dómini ad Jonam Prophétam secúndo, dicens: Surge, et vade in Níniven civitátem magnam: et prǽdica in ea prædicatiónem, quam ego loquor ad te. Et surréxit Jonas, et ábiit in Níniven juxta verbum Dómini. Et Nínive erat civitas magna itínere trium diérum. Et cœpit Jonas introíre in civitátem itínere diéi uníus: et clamávit et dixit: Adhuc quadragínta dies, et Nínive subvertétur. Et credidérunt viri Ninivítæ in Deum: et prædicavérunt jejúnium, et vestíti sunt saccis a majore usque ad minórem. Et pervénit verbum ad regem Nínive: et surréxit de sólio suo, et abjécit vestiméntum suum a se, et indútus est sacco, et sedit in cínere. Et clamávit et dixit in Nínive ex ore regis et príncipum ejus, dicens: Hómines et juménta et boves et pécora non gustent quidquam: nec pascántur, et aquam non bibant. Et operiántur saccis hómines et juménta, et clament ad Dóminum in fortitúdine, et convertátur vir a via sua mala, et ab iniquitáte, quæ est in mánibus eórum. Quis scit, si convertátur et ignóscat Deus: et revertátur a furóre iræ suæ, et non períbimus? Et vidit Deus ópera eórum, quia convérsi sunt de via sua mala: et misértus est pópulo suo Dóminus, Deus noster."}],"Graduale":[{"k":"ref","la":"Ps 53:4, 3"},{"k":"text","la":"Deus, exáudi oratiónem meam: áuribus pércipe verba oris mei."},{"k":"text","la":"Deus, in nómine tuo salvum me fac, et in virtúte tua líbera me.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 102:10"},{"k":"text","la":"Dómine, non secúndum peccáta nostra, quæ fécimus nos: neque secúndum iniquitátes nostras retríbuas nobis."},{"k":"ref","la":"Ps 78:8-9"},{"k":"text","la":"Dómine, ne memíneris iniquitátum nostrárum antiquárum: cito antícipent nos misericórdiæ tuæ, quia páuperes facti sumus nimis. (Hic genuflectitur)","mark":"V"},{"k":"text","la":"Adjuva nos, Deus, salutáris noster: et propter glóriam nóminis tui, Dómine, líbera nos: et propítius esto peccátis nostris, propter nomen tuum.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem."},{"k":"ref","la":"Joann 7:32-39"},{"k":"text","la":"In illo témpore: Misérunt príncipes et pharisǽi minístros, ut apprehénderent Jesum. Dixit ergo eis Jesus: Adhuc módicum tempus vobíscum sum: et vado ad eum, qui me misit. Quærétis me, et non inveniétis: et ubi ego sum, vos non potéstis veníre. Dixérunt ergo Judǽi ad semetípsos: Quo hic itúrus est, quia non inveniémus eum? numquid in dispersiónem géntium itúrus est, et doctúrus gentes? Quis est hic sermo, quem dixit: Quærétis me, et non inveniétis: et ubi sum ego, vos non potéstis veníre? In novíssimo autem die magno festivitátis stabat Jesus, et clamábat, dicens: Si quis sitit, véniat ad me et bibat. Qui credit in me, sicut dicit Scriptúra, flúmina de ventre ejus fluent aquæ vivæ. Hoc autem dixit de Spíritu, quem acceptúri erant credéntes in eum."}],"Offertorium":[{"k":"ref","la":"Ps 6:5"},{"k":"text","la":"Dómine, convértere, et éripe ánimam meam: salvum me fac propter misericórdiam tuam."}],"Secreta":[{"k":"text","la":"Concéde nobis, Dómine, Deus noster: ut hæc hóstia salutáris et nostrórum fiat purgátio delictórum, et tuæ propitiátio majestátis."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 23:10"},{"k":"text","la":"Dóminus virtútum ipse est Rex glóriæ."}],"Postcommunio":[{"k":"text","la":"Sacraménti tui, quǽsumus, Dómine, participátio salutáris, et purificatiónem nobis tríbuat, et medélam."},{"k":"macro","name":"Per Dominum"}],"Super populum":[{"k":"rubric","la":"Oratio super populum"},{"k":"text","la":"Orémus."},{"k":"text","la":"Humiliáte cápita vestra Deo."},{"k":"text","la":"Da, quǽsumus, Dómine, pópulo tuo salútem mentis et córporis: ut, bonis opéribus inhæréndo, tua semper mereátur protectióne deféndi."},{"k":"macro","name":"Per Dominum"}]},"hr":{"d676560a8314c5bd":{"t":"Ps 55, 2, Ps 55, 3\n(Ps 55, 2) Smiluj mi se, Bože, jer me zlostavljaju ljudi, po sav dan me napadaju i dosađuju mi. (Ps 55, 3) Po cijeli dan me muče neprijatelji moji, ima ih mnogo koji se bore protiv mene. (Ps 55, 2) Smiluj mi se, Bože, jer me zlostavljaju ljudi, po sav dan me napadaju i dosađuju mi. [u vremenu Muke ne govori se Slava Ocu u sklopu Ulazne pjesme]","kn":"(Ps. 55, 2). Smiluj mi se, Gospodine, jer me gaze, cijeli dan navaljuje na me neprijatelj. (Ps- 55, 3). Cijeli dan navaljuju na me neprijatelji i mnogo ih ima! Smiluj mi se . . .","knRef":"Kniewald 1942, str. 198–199 (snimka 100) (OCR)"},"17b369fcf27df11b":{"t":"<i>Pomolimo se</i>.\nPosveti, molimo, Gospodine, naše postove i udijeli nam oproštenje svih naših grijeha.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Posveti, molimo. Gospodine, naše postove, i blagostivo nam dairuj oprošten je svih krivica, po G. n.","knRef":"Kniewald 1942, str. 198–199 (snimka 100) (OCR)"},"826940e27be84326":{"t":"Jon 3, 1-10\nČitanje Jone proroka. U one dane zapovijedi Gospodin proroku Joni po drugi put: Ustani i pođi u veliki grad Ninivu i u njemu propovijedaj ono što ti ja govorim. Ustane Jona i po Gospodnjoj riječi pođe u Ninivu. A Niniva je bio velik grad, tri dana hoda. I Jona je obilazio grad jedan dan vičući: Još četrdeset dana i Niniva će propasti. Ninivljani povjerovaše Bogu, proglase post, obuku se u kostrijet, svi, veliki i mali. I ti glasovi dopru do kralja, koji siđe sa svoga prijestolja, skine sa sebe svoje odijelo, obuče se u kostrijet i sjede u pepeo. Kraljevski su i kneževski glasnici vikali po Ninivi: Ljudi i životinje, volovi i ovce da ne okuse ništa! Neka ne pasu i ne napajaju se! Neka se pokriju kostrijetom ljudi i životinje! Neka zazivaju Gospodina! Neka se odvrate ljudi od svoga zla i opakih nedjela svojih ruku! Možda će nam se smilovati Bog, oprostiti nam i popustiti od svojega gnjeva da ne izginemo. I vidje Bog njihova djela i smilova se svojem narodu Gospodin naš Bog.","kn":"Čitanje Jone Proroka (3, 1-10). U one dane; Dođe riječ Gospodnja Joni proroku drugi put govoreći: Ustani i idi u Ninivu, grad veliki: i propovijedaj u njemu ono, što ti ja govorim. I ustade Jona, i pođe u Ninivu po riječi Gospodnjoj. A Niniva bijaše gred veliki, tri dana hoda. I Jona poče ići po gradu jedan dan vičući, i govoreći: Još četrdeset dana, i Niniva će propasti. I povjerovaše Ninivljani Bogu i oglasiše post i obukoše se u kostrijet od najvećega do najmanjega. I dopre riječ do kralja Ninivskoga; i sade sa svojega prijestolja, 1 skine sa sebe svoje odijelo i obuče se u kostrijet: i sjede u pepeo. I glasnik kraljev i knezova njihovih vikaše po Ninivi govoreći: Ljudi, i životinje, 1 volovi, i ovce, da ne okuse ništa: ni da pasu ni da piju vode. Neka se pokriju kostrijeti, ljudi, i životinje, i neka prizlvlju Gospodina jako, neka se odvrati čovjek od svoga zla puta, i od bezakonja, koje im je u rukama. Ko zna, da se ne umilostivi Bog, i oprosti i popusti od žestokog gnjeva svojega, te ne izginemo? I vidje Bog djela njihova: i smilova se puku svome, Gospodin Bog nas.","knRef":"Kniewald 1942, str. 198–199 (snimka 100) (OCR)"},"e2a0a7e98b72af98":{"t":"Ps 53, 4 i 3\nUsliši, Bože, molitvu moju, poslušaj riječi usta mojih. Spasi me, Bože, po imenu svome, i oslobodi me snagom svojom.\n\nPs 102, 10, Ps 78, 8-9\n(Ps 102, 10) Gospodine, ne uzvrati nam prema našim grijesima koje smo učinili, niti prema našim krivicama. (Ps 78, 8-9) Gospodine, ne sjećaj se naših starih zloća, brzo neka nam dođe ususret tvoje milosrđe, jer postadosmo vrlo bijedni. [Ovdje se poklekne] Pomozi nam, Bože Spasitelju naš, i radi slave svojeg imena izbavi nas, Gospodine. Imaj samilosti s našim grijesima radi imena svojega.","kn":"(Ps. 53, 4, 3). Bože, usliši molitvu moju, čuj riječi usta mojih, Bože, imenom svojim spasi me i krepošću svojom opravdaj me!\n\n(Ps. 102, 10). Gospodine, ne postupaj s nama po grijesima našim i ne vraćaj nam po nepravdama našim. (Ps. 78, 8, 9) Gospodine, ne opominji se pređašnjih bezakonja naših, već neka nas brzo preteče milosrđe Tvoje, jer smo postali veoma ubogi (Ovdje se poklekne.) Pomozi nam. Bože, spasitelju naš, i radi slave imena svoga izbavi nas. Gospodine, i očisti nas od grijeha naših radi imena svoga.","knRef":"Kniewald 1942, str. 198–199 (snimka 100) (OCR)"},"387ed11a6a9c4c15":{"t":"Iv 7, 32-39\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme svećenički poglavari i farizeji pošalju sluge da uhvate Isusa. Tada im Isus reče: Još sam s vama malo vremena, pa se vraćam k onome koji me posla. Tražit ćete me, ali me nećete naći. Gdje budem ja vi ne možete doći. Tada rekoše Židovi među sobom: Kamo ovaj kani poći da ga mi nećemo naći? Da ne ide k Židovima rasijanima među nevjernicima poučavati ih? Što znači riječ koju je izgovorio: Tražit ćete me, ali me nećete naći? A posljednjega i najsvečanijega dana Isus je stajao i vikao: Tko žeđa neka dođe k meni i pije. Tko vjeruje u mene, kako kaže Pismo, u njemu će provreti potoci žive vode. Ovo reče za Duha koga su imali primiti svi oni koji vjeruju u njega.","kn":"t Slijedi sv. evanđelje po Ivanu (7, 32-39). U ono vrijeme poslaše farizeji i glavari svećenički sluge, da uhvate Isusa. Ali Isus im reče: Još sam s vama malo vremena, pa idem k onomu, koji me je poslao. Tražit ćete me, i ne ćete me naći, i gdje sam ja, vi ne možete doći. Tada rekoše Zidovi među sobom: Kamo kani ovaj ići, da ga mi ne ćemo naći? Ta valjda ne kani ići Zidovima rasijanim među poga, nima i učiti pogane? Sto znači ova riječ, koju reče: Tražit ćete me, i ne ćete me naći, i gdje sam ja, vi ne možete doći? U posljednji veliki dan blagdana stade Isus i povika: Tko je žedan, neka dođe k meni i pije! Tko vjeruje u mene, kako kaže Pismo: rijeke će žive vode poteći iz njegova tijela. A ovo reče za Duha, kojega su imali primiti oni, koji vjeruju u njega.","knRef":"Kniewald 1942, str. 198–199 (snimka 100) (OCR)"},"f6b18c7474825d4d":{"t":"Ps 6, 5\nObazri se, Gospodine, i izbavi moju dušu. Spasi me poradi milosrđa svoga.","kn":"(Ps. 6, 5). Povrati se. Gospodine, i Izbavi dušu moju, spasi me poradi milosrđa svoga!","knRef":"Kniewald 1942, str. 198–199 (snimka 100) (OCR)"},"91520e023f693f52":{"t":"Daj nam, Gospodine, Bože naš, da nas ova spasonosna žrtva očisti od naših grijeha i umilostivi tvoje veličanstvo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Dopusti nam. Gospodine, Bože naš, da nam ova spasonosna žrtva bude i očišćenje naših grijeha i ublažen je Tvoga veličanstva, po G. n.","knRef":"Kniewald 1942, str. 198–199 (snimka 100) (OCR)"},"f2fb1fe68f386b18":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti si odredio spasenje ljudskog roda po drvu Križa, da se opet rodi život ondje gdje je nikla smrt, i onaj koji je na drvu pobijedio, bude pobijeđen na drvu po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glas primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu_ je dostojno i pravedno, pravo i. spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vječni Bože, po Kristu, 1 Gospodinu: našemu: jer Ti si ustanovio spase- I nje ljudskog roda na drvetu križa, da odanle us krsne život, odakle je proizašla smrt, te onaj, koji je na drvetu iznio pobjedu, na drvetu bude i svla- J dan po Kristu, Gospodinu našem, po kojem veličan stvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti, Nebesa Te i nebeske moći i blaženi Serafini zajedno slave, Zapovjedi, molimo, da se s njima smiju sjediniti i naši glasovi, koji govore u smjernom ispovijedanju:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"5f9bd2cea0609d80":{"t":"Ps 23, 10\nGospodin nad vojskama je Kralj slave.","kn":"(Pb. 23, 10). Gospodin nad vojskama, on je Kralj slave!","knRef":"Kniewald 1942, str. 200–201 (snimka 101) (OCR)"},"242666e598d912ef":{"t":"<i>Pomolimo se</i>.\nSpasonosno primanje tvoga otajstva neka nam, molimo, Gospodine, ostvari očišćenje i ozdravljenje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"dee1da17709a9d8d":{"t":"<i>Pomolimo se</i>.\n<i>Prignite pred Bogom svoje glave</i>.\nDaj, molimo, Gospodine, svome narodu zdravlje duše i tijela da revan u dobrim djelima zavrijedi da ga uvijek brani tvoja zaštita.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pomolimo se! Prignite ponizno glave svoje pred Bogom! Podaj,, molimo. Gospodine, puku svomu zdravlje duše i tijela, da prianjajući uz dobra djela uvijek zaslužuje Tvoju zaštitu i obranu, po G. n.","knRef":"Kniewald 1942, str. 200–201 (snimka 101) (OCR)"}}});
